/* The Vault – Hollow Suit (Buch S. 112–129). Übersetzung aus dem Englischen. */
window.TA_VAULT = window.TA_VAULT || {};
TA_VAULT["hollow-suit"] = {
 cw: "Gedächtnisverlust",
 chaosP: 117,
 chaos: [
  {k:2, n:"Verderben", en:"Corrupt", x:"Physische Dinge, die mit von Aldir gelöschten Marken verbunden sind, verschwinden ebenfalls oder verlieren ihr ursprüngliches Branding. Das geschieht nicht automatisch, würde aber mit genug Zeit vermutlich bei allen gelöschten Marken passieren."},
  {k:4, n:"Manifestieren", en:"Manifest", x:"Aldir setzt vorrangig täuschende Anomalien ein. Die meisten davon sind Leere Anzüge: menschenähnliche Führungskräfte-Marionetten, die Aldirs Willen ausführen. Wenn er die Gelegenheit bekommt, erschafft er außerdem Nachbildungen von Filmstars und wichtigen politischen und historischen Persönlichkeiten, um Agenten zu verwirren."},
  {k:5, n:"Anziehen", en:"Attract", x:"**Virales Marketing:** Aldir kann die Aufmerksamkeit auf den nächstgelegenen Bildschirm lenken. Menschen fühlen sich unter Umständen gezwungen, so schnell wie möglich die beworbene Serie auf dem gerade greifbaren Gerät zu schauen – oder sich an einen Ort zu begeben, auf den der Bildschirm sie hinweist."},
  {k:8, n:"Versetzen", en:"Displace", x:"**Asset-Nullifizierung:** Ziele werden in eine chaotische Müllhalde von allem versetzt, was jemals „aus steuerlichen Gründen nullifiziert“ wurde. Beliebte Anime-Serien existieren dort gleichzeitig mit Sentai-Serien, schwarz-weißen Sitcom-Klassikern und einer seit Ewigkeiten laufenden Polizeiserie. Dieses schillernde Labyrinth der Popkultur ist ebenso ablenkend wie verwirrend und soll das Opfer festsetzen, damit Aldir Zeit gewinnt, sich neu zu sammeln."},
  {k:6, n:"Ausdehnen", en:"Expand", x:"**Übernahmen:** Aldir kann Ausdehnen einsetzen, um Medienmarken innerhalb seiner Domäne sowie Orte an sich zu bringen. Sobald Medienmarken in seiner Domäne sind, kann er sie Eliminieren, um dem Pool Chaos hinzuzufügen."}
 ],
 ziele: [
  {art:"bel", n:1, x:"für das Verbessern einer Tour für die anderen Touristen"},
  {art:"bel", n:3, x:"dafür, dass ein Pitch grünes Licht bekommt"},
  {art:"ver", n:1, x:"für Sachbeschädigung im Stadtarchiv"}
 ],
 sonder: [
  {t:"kasten", h:"Sonderregeln", b:[
   "Jedes Mal, wenn Aldir Schaden nehmen würde, aktiviert er sofort und kostenlos den Erfolgseffekt der Absence-Fähigkeit **Missed**.",
   "Aldir darf die Gun-Fähigkeit **Eliminate** nach Belieben einsetzen, aber nur für Serien und physische Gegenstände, die in seiner Domäne existieren oder durch seinen Chaos-Effekt Ausdehnen erworben wurden. Wenn er das tut, kann er einen Chaos-Effekt im Wert von 10 Chaos oder weniger (außer Ausdehnen) wählen und kostenlos aktivieren.",
   "Aldir darf jederzeit frei zwischen seiner anomalen Erscheinung und seiner „menschlichen Maske“ wechseln."
  ]}
 ],
 reiter: {
  profil: [
   {t:"Fundstück", p:113, b:[
    {t:"drehbuch", h:"HOLLOW SUIT – von Carlos Cisco", x:[
     "INNEN. BÜRO DES CEO, RETROFLIX STUDIOS – ABEND",
     "Ein Hauch Make-up auf einer Wange. Ein Schwamm entfernt behutsam die Schminke vom Rand eines präzise gestylten Bartes. Ein Lichtblitz, als der Raum heller wird. Das Klicken und Surren einer Kamera, die sich aufspult.",
     "Ein hochkarätiges Interview im Eckbüro des CEO der Retroflix Studios. Softboxen umringen einen massiven Eichenschreibtisch mit dem geschnitzten Relief von einem Dutzend beliebter Anime-, Sitcom- und Polizeiserien-Figuren, deren Abbilder allesamt dem Unternehmen gehören.",
     "Hinter dem Schreibtisch sitzt ALDIR CROMBLAINO, der CEO der Retroflix Studios. Sein hochlehniger Stuhl und der gewaltige Schreibtisch ragen über dem REPORTER auf, der im Stuhl gegenüber sitzt. Der Reporter sackt in seinen Sitz, schwach und unterwürfig vor diesem gut gekleideten und makellos gepflegten Mann.",
     "Der Reporter räuspert sich.",
     "**REPORTER:** Mr. Cromblaino, ich wollte–",
     "**ALDIR:** Aldir reicht völlig.",
     "**REPORTER:** Richtig. Aldir, ich wollte Sie zu Ihrer jüngsten Geschäftsstrategie befragen, die in den Chefetagen der ganzen Stadt in aller Munde ist. Ich spreche natürlich von der Asset-Nullifizierung.",
     "**ALDIR:** Bei den Streaming-Kriegen geht es darum, die Augen dorthin zu lenken, wo sie hinmüssen. Das Problem unserer Branche ist: Es gibt zu viele Dinge und zu wenige Augen. Wenn wir die Gesamtlast verringern, können wir unsere Anstrengungen auf die Produktion der hochwertigsten Inhalte konzentrieren, die die meisten Sehminuten bringen.",
     "**REPORTER:** Es geht also darum, die Qualität zu steigern. Kein Steuertrick, wie manche behauptet haben–",
     "**ALDIR:** Lassen Sie mich Sie genau da unterbrechen … ähm … na ja, Ihr Name spielt keine Rolle. Oder bald nicht mehr. Bei der Asset-Nullifizierung geht es darum, das Fett abzuschneiden. Diese Welt ist so aufgebläht von Inhalten, dass sie den gesamten Pool verwässert hat. Ich versuche lediglich, dieses Fett in etwas weniger Belastendes zu verwandeln.",
     "**REPORTER:** Gehen wir weiter: Der CEO von 21st Century Cat hat Sie öffentlich gerügt und gesagt, Sie würden „gar nichts erschaffen“. Sie seien nicht „dafür gebaut“. Haben Sie dazu etwas zu sagen, oder zu den Fragen, die in letzter Zeit zu Ihrer Identität aufgeworfen wurden?",
     "Die Lichter blitzen grell auf. Als der Blitz verblasst, sitzt Aldir noch immer an seinem Schreibtisch und sieht gelangweilt aus. Der Reporter, die Crew … alle anderen im Raum sind verschwunden.",
     "Aldir blickt an dem leeren Stuhl vor ihm vorbei. An der Rückwand laufen Dutzende Fernseher mit ebenso vielen verschiedenen Serien. Sein Blick huscht über schwarz-weiße Sitcoms, Polizeiserien und Anime-Klassiker und bleibt an einem Bild von Teenagern in bunten Anzügen hängen, die gegen riesige Monster kämpfen. Eine Sentai-Serie der 90er, aus Japan importiert.",
     "Er hebt die Hand, als hielte er eine Fernbedienung. Er deutet an, einen Knopf zu drücken, und der Fernsehbildschirm flimmert. Wenige Augenblicke später verschwimmt das Bild und verpixelt, dann quillt es aus dem Fernseher als zähflüssiges Ichor in Grundfarben.",
     "Aldir tritt hinter dem Schreibtisch hervor und geht hinüber zur Pfütze. Er steigt hinein, und sie hebt sich, breitet sich nach oben und um seinen Körper aus. In der Verzerrung durch die Flüssigkeit verschwindet Aldir, verhüllt von wechselnder Farbe.",
     "Als die Sonne untergeht, verdunkelt sich der Raum und lässt nur das Leuchten der Fernseher zurück, das sich auf dem glänzenden Kokon spiegelt."
    ]}
   ]},
   {t:"Überblick", p:114, b:[
    {t:"profil",
     lead:"Retroflix ist ein aufstrebendes Studio, das Nostalgie erntet, neu verpackt und verscherbelt. Im Zentrum seiner jüngsten Übernahmen steht eine Anomalie, die einst die kreativen Impulse von Autoren, Filmemachern und Animatoren speiste und sie zu neuen kinematografischen Höhen trug – doch die Schließung ihres Studios machte sie vor langer Zeit zum Hollow. Nun, in Gestalt einer mächtigen Studio-Führungskraft, verschlingt diese Anomalie Bruchstücke popkultureller Ephemera, um ihr Dasein zu erhalten. Wenn sie das tut, verschwinden diese Medienschnipsel vollständig aus der Erinnerung.",
     fokus:"Aldirs ursprünglicher Fokus – die kreative Produktion zu maximieren – ist verloren, und die Anomalie ist längst zum Hollow geworden. Um nicht zu sterben, entdeckte die Anomalie einen neuen Weg zu überleben: das Verschlingen kreativer Ephemera. Indem er Geistiges Eigentum erwirbt und es aus der Realität entfernt, nachdem er die darauf gerichtete Aufmerksamkeit maximiert hat, kann er unsere Erinnerungen und Emotionen verspeisen, die mit den Serien verbunden sind.",
     domaene:"Retroflix Studios, sein sich ständig ausbreitendes Streaming-Studio, dessen Reichweite täglich wächst, sowohl physisch als auch digital. Aldir erhält Domänen-Boni überall dort, wo Medienmarken von Retroflix betrachtet werden.",
     impuls:"Aldir verzehrt Nostalgie und Erinnerung, um zu überleben. Er hat seinen ursprünglichen Fokus, seinen emotionalen Anker, nicht mehr, also lebt er davon, die anderer zu nehmen. Aldir führt das Geschäft wie ein Hütchenspiel: Er macht die Öffentlichkeit süchtig nach einer Serie, nur um sie „aus steuerlichen Gründen“ zu „vaulten“. Tatsächlich verzehrt Aldir die emotionale Resonanz, die an eine Serie gebunden ist, sobald sie einen bestimmten Popularitätsindex erreicht hat.\n\nAlles, was ein Fan in seine Hingabe an eine Serie steckt – Loyalität, tiefes Wissen, Liebe – ist nur Futter für die Mühle. Danach vergisst jeder, der diese Serien über die Streaming-Plattform konsumiert, dass es sie je gab. Jedes Mal, wenn das geschieht, verlängert sich Aldirs Leben und sein Aktienkurs steigt."},
    {t:"h", x:"Geschichte"},
    "In den frühen 90ern schoss Rare Import Studios zum Erfolg, indem es frühe Anime- und Sentai-Serien importierte und neu verpackte. Das Studio wurde innerhalb des Jahrzehnts von einer Risikokapitalgesellschaft gekauft und bis auf die Einzelteile ausgeschlachtet. Zurück blieb, allein unter einer Soundstage, eine Anomalie. Einst inspirierte sie die Menschen, die hier arbeiteten … doch am Ende ließen sie sie zurück. Die Anomalie, die diesen Ort einst großgemacht hatte, wurde durch den Verlust zum Hollow – und begann, die Köpfe zu verabscheuen, die sie hervorgebracht hatten.",
    "Schnitt auf heute. Der heiße neue Name in der Fernsehbranche von Ternion City ist Aldir Cromblaino (er/ihm), der geheimnisvolle neue CEO von Retroflix, einem Unternehmen, das sich dem Aufkauf der verstreuten Teile von Rare Imports Studios und anderer nostalgischer Inhalte widmet, um sie als Kern einer Streaming-Plattform zu verwenden. Er hat sich einen Ruf als gewiefter und gefräßiger Aufkäufer von Medien erarbeitet, die nicht mehr im Umlauf sind: Er hostet sie nur auf Retroflix und entfernt sie dann plötzlich ohne Vorwarnung. Niemand weiß, woher er kam oder wie er so schnell zu Prominenz gelangte – aber er weiß, was die Leute wollen, weiß, wie er es ihnen gibt, und nimmt es ihnen immer weg, wenn ihre Bindung ihren Höhepunkt erreicht hat.",
    "In Wahrheit ist Aldir die Anomalie von Rare Import Studios, noch am Leben und mit einer perfekt entwickelten menschlichen Gestalt. In den vergangenen 30 Jahren hat er gelernt, als Hollow zu überleben, indem er menschliche Gestalten annimmt und gelegentlich Menschen verzehrt, um stabil zu bleiben. Aldir lernte, dass diese Methode ihn nur kurze Zeit am Leben hält, und wandte sich schließlich größerer Beute zu: unseren kreativen Ephemera. Kunst enthält die konzentrierte Energie vieler Köpfe, und bei einem solchen Überangebot an Medien … wer würde schon bemerken, wenn ab und zu ein paar Serien verschwinden? Was auch immer Aldir einmal war, jetzt ist er nichts als ein hohler Anzug (hollow suit), dessen einzige echte Antriebe Konsum und Wachstum sind.",
    {t:"h", x:"Erscheinung"},
    "Aldir trägt jeden Tag denselben Nadelstreifenanzug. Der feinste Schnitt und Stoff. Wer ein Meeting mit ihm hat, verlässt es mit summenden Emotionen, wirbelndem Kopf, einem rostartigen Geschmack im hinteren Mundraum und dem Geruch frisch gemähter Grasschnipsel in der Erinnerung. Aldirs Gesicht ist eine kunstvoll gefertigte Maske, geschliffen über sein außergewöhnlich langes Leben. Hinter der Maske liegt seine wahre Gestalt: ein gasförmiger, mehrfarbiger Wirbel. Der trägt trotzdem den Anzug. In der Stille wird seine Gegenwart von einem leisen Summen begleitet. Wie eine Stechmücke, die am Rand des Hörbaren schwebt.",
    {t:"h", x:"Aktuelle Lage"},
    "Aldirs Plan wird durch physische Medien erschwert. Während jeder, der über die Streaming-Plattform geschaut hat, alle Erinnerungen an die Marken verliert, sobald sie gelöscht werden, existieren die physischen Medien weiter – und viele Leute zahlen nicht für Retroflix. Das kulturelle Gedächtnis ist nun gespalten: in diejenigen, die sich nur an das Schauen in einem klassischen Format erinnern, und diejenigen, die auf dem Streamingdienst geschaut haben. Ein herausragender Fall, in dem ein ehemaliger Star seine Karriere bei Rare Import Studios vergessen hat, hat die Aufmerksamkeit der Agency erregt."
   ]}
  ],
  vor: [
   {t:"Morgenbesprechung", p:115, b:[
    {t:"morgen", x:[
     "Eine junge Beziehung wurde kürzlich als Superfan der 90er-Hitserie Totally Transmorphic Teenage Marshals eingeführt, kann sich aber nicht mehr erinnern, warum ihr Zimmer mit den Postern tapeziert ist.",
     "Eine Nachricht geht um: Retroflix nimmt aus steuerlichen Gründen alle 1200 Folgen des beliebten Animes Single Segment aus dem Programm. Kurz darauf sind die Nachricht und die Diskussion darüber nirgends mehr zu finden.",
     "Das Familienmitglied eines Agenten räumt alte Sachen aus und lädt ihn ein, in Erinnerungen an die Serien und Geschichten zu schwelgen, die er als Kind geliebt hat.",
     "In der Agency müssen die Agenten an einer „Entlassungsübung“ teilnehmen, bei der jeder Angestellte die Schritte einübt, die im Fall plötzlicher Massenentlassungen zu befolgen sind."
    ]}
   ]},
   {t:"Einsatzbesprechung", p:115, b:[
    {t:"vorlesen", b:[
     "Gestern, während eines Livestreams, hat ein Schauspieler namens Marcos Lita (er/ihm) vergessen, wer er ist. Marcos streamte ein „Reaction Watch“ einer TV-Serie namens Totally Transmorphic Teenage Marshals (TTTM), einer Sentai-Serie der 90er. Marcos spielte die Hauptrolle der Serie. Er war der Rote. Mitten in einer Folge vergaß er plötzlich, warum er diese Serie überhaupt schaute und dass er je darin mitgespielt hatte. Seitdem hatte er mehrere Zusammenbrüche in den sozialen Medien, da er immer mehr physischen Merch dieser Serie entdeckt hat, auf dem er zu sehen ist, die er scheinbar überhaupt nicht mehr kennt. Die Agency hat den ursprünglichen Stream zur Durchsicht der Agenten archiviert, dazu die Adresse der Lagereinheit, von der aus er gerade streamt.",
     "Die Agency hält die Geschwindigkeit und Vollständigkeit seines Gedächtnisverlusts für möglicherweise anomalen Ursprungs – es liegt an den Agenten herauszufinden, was wirklich vor sich geht."
    ]},
    {t:"hinweis", art:"gew", h:"Die Agenten können sich eine Aufzeichnung des ursprünglichen Streams ansehen, mit den folgenden Höhepunkten:", x:[
     "Die Folge, die er gerade schaut (und vergisst!), ist eine berühmte, ein Fanliebling, in der der geheimnisvolle Viridian Marshal auftaucht und die Helden mit ihrem MechaKaiju in die Tonne kloppt.",
     "„Okay, Leute. Ich weiß, ich habe jahrelang auf die Serie geschissen. Hab mich geweigert, sie zu schauen, und wollte mich einfach komplett davon distanzieren. Aber Scheiße … ich muss sagen, ihr hattet recht. Der Viridian-Marshal-Handlungsbogen ist so verdammt gut–… Sorry. Ich … äh … hab den Faden verloren. Was ist … Was ist das für eine Serie?“",
     "Der Livestream verliert Zuschauer. Kommentare wie „Wer ist der Typ?“ und „Welchen Kanal schau ich hier?“ ziehen vorbei. Marcos wirkt verwirrt, bedrückt. Er sieht zu, wie die nächste Folge automatisch startet. „Was zum Teufel ist das?“, und als im Intro sein Gesicht und sein Name erscheinen, klappt ihm die Kinnlade herunter. Der Stream bricht abrupt ab."
    ]},
    {t:"hinweis", art:"gew", h:"Marcos streamt gerade live aus einer Lagereinheit:", x:[
     "Marcos steht vor einer Lagereinheit und erzählt, dass er einen Schlüssel mit der Aufschrift „TTTM“ hat. Wie die Serie. Er öffnet sie. Sie ist voller Merch. Merch mit seinem Gesicht darauf. Pressemappen, Fotos. Als wären all seine Erinnerungen an diese Serie in diesem Lagerabteil weggestopft worden.",
     "Er ist zugleich beflügelt und untröstlich. Beim Anblick dieser Sachen wird klar: sein Einfluss auf die Fangemeinde. Er schätzt es zum ersten Mal, mit frischen Augen.",
     "„Ich dachte, ich hätte nie meinen großen Durchbruch gehabt … Und ich … habe mich dafür geschämt, als ich ihn hatte? Was habe ich mir dabei gedacht?“",
     "Eine Frau außerhalb des Bildes sagt: „Ich hab’s dir gesagt, Schatz. Ich war immer so stolz auf dich.“",
     "Ein anderer Mann außerhalb des Bildes sagt: „Wovon redet ihr zwei? Marcos war nie in einer Serie. Wer hat überhaupt schon mal von der Serie gehört?“",
     "Marcos blickt auf sein verschwundenes Vermächtnis hinab. Er schaut in die Kamera. „Ich kläre das. Ihr zwei könnt gehen.“"
    ]}
   ]}
  ],
  erm: [
   {t:"Merch-Lager", p:118, b:[
    "Die STORE-IT-ALL-Lagereinheiten liegen eine kurze Autofahrt außerhalb der Stadt. Drei eingeschossige beige Gebäude sind in einige Dutzend einzelne Einheiten verschiedener Größe aufgeteilt, jede mit einem Rolltor, das direkt nach draußen führt. STORE-IT-ALL hat keine menschlichen Wachen und verlässt sich auf Überwachungskameras, die von einem anderen Ort aus beobachtet werden. Außer Marcos ist niemand hier.",
    "Marcos Lita (er/ihm) wühlt sich durch eine Lagereinheit voller Merch, Fanpost und anderer Ephemera von Totally Transmorphic Teenage Marshals (TTTM) aus seiner Popkultur-Vergangenheit. Er streamt nicht mehr, und seine Verwirrung ist in Frustration umgeschlagen.",
    "Als die Agenten ankommen, wirft er seine Habseligkeiten auf einen Haufen, kippt Kisten aus und grummelt darüber, wie wenig Informationen unter den Merchandise-Artikeln zu finden sind.",
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten, wenn sie einen Vorwand finden, um Marcos anzusprechen, oder die Zeitschriften in seiner Lagereinheit durchsehen:", x:[
     "Offenbar war er der Crimson Marshal, der jugendliche Anführer der Transmorphic Marshals, einer beliebten Sentai-Serie der 90er, aus der eine Reihe von Spin-offs hervorging. Aber er erinnert sich an nichts davon.",
     "Er hatte die Serie nie geschaut, aus Scham. Laut mehreren Zeitschrifteninterviews, die er gab, hat er seine ganze Karriere damit verbracht, sich von etwas zu distanzieren, das so vielen Menschen Freude bereitet hat. Das zerreißt ihn, und er ringt mit Reue für Verhalten, an das er sich überhaupt nicht erinnert."
    ]},
    {t:"h", x:"Familienunterstützung"},
    "Carmen (sie/ihr), Marcos’ Mutter, und Alberto (er/ihm), Marcos’ Bruder, sitzen in der Nähe in einem Truck. Als die Agenten sich nähern, streiten sie darüber, was mit Marcos geschieht.",
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten, wenn sie mit Carmen und Alberto sprechen oder sie belauschen:", x:[
     "Carmen erinnert sich an die Serie und besitzt eine physische Sammlung signierter Blu-rays.",
     "Alberto hat keinerlei Erinnerung daran, dass es sie je gab, aber Carmen erinnert sich, dass er sie letztes Jahr komplett geschaut hat – auf Retroflix. Sie weiß es sicher, weil sie sich darüber aufgeregt hat, dass er sich über Marcos in der Rolle des Crimson Marshal lustig gemacht hat."
     ]},
    {t:"h", x:"Retroflix unter die Lupe nehmen"},
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten, wenn sie das Internet oder andere Methoden nutzen, um Retroflix zu recherchieren:", x:[
     "Retroflix ist ein Streamingdienst für nostalgische Inhalte aus den 80ern bis in die frühen 2000er. Er hat seinen Sitz in den ehemaligen Büros und TV-Produktionsgebäuden von Rare Import Studios, die jahrelang ungenutzt waren. Die Adresse ist leicht zu finden.",
     "Der CEO von Retroflix ist Aldir Cromblaino. Er hat mehrere Interviews zu seiner Strategie der „Asset-Nullifizierung“ gegeben, einer obskuren Methode, den Unternehmenswert zu steigern, indem man geistiges Eigentum aus dem Umlauf nimmt. Über die Zeit vor der Gründung von Retroflix findet sich nichts über ihn.",
     "Retroflix Studios bietet täglich Touren über das Gelände an, aber es sind keine Tickets mehr übrig. Zum Glück hat Marcos noch ein paar übrig."
    ]},
    {t:"kasten", cls:"hs-klappe", h:"Marcos’ Plan", b:[
     {t:"liste", x:[
      "Er will der Sache auf den Grund gehen und wird den Agenten helfen, wenn sie das auch tun. Er vermutet, dass es etwas mit Retroflix zu tun hat, weil seine Mutter sagt, alles sei in Ordnung gewesen, bis die Serie auf ihrem Streamingdienst hochgeladen wurde. Er wird alles tun, was er kann, um die Agenten zu unterstützen, wenn sie Interesse daran zeigen, Retroflix zu untersuchen.",
      "Seine Fundgrube an Primärquellen aus jener Zeit kann den Agenten bei dem helfen, was kommt. Jedes Behind-the-Scenes-Foto stammt von derselben Soundstage, die für jeden Schauplatz in der Lokalisierung der Serie immer wieder umfunktioniert wurde. Marcos scheint dort mehrere Jahre lang in diesem Gebäude gearbeitet zu haben – er hofft, dass der Anblick der Soundstage seine Erinnerung wieder anstoßen könnte.",
      "Marcos plant, an einer Studio-Tour von Retroflix teilzunehmen, um nach der Soundstage zu suchen, da sie der einzige durchgehende Hinweis in dieser Fundgrube ist. Er hat die letzten Tickets der heutigen Tour selbst gekauft, in der Absicht, Familie anzuwerben, die ihm beim Wegschleichen hilft, aber er wird seinen Plan ändern, um mit den Agenten zusammenzuarbeiten."
     ]}
    ]}
   ]},
   {t:"Retroflix Studios", p:119, b:[
    "Retroflix befindet sich mitten in einer umfassenden Renovierung, wobei mehrere Bereiche des Geländes für Besucher abgesperrt sind. Die klassischen cremeweißen Art-déco-Gebäude werden durch ultramoderne, sterile Firmenbüros ersetzt.",
    "Die Tour führt durch Kulissen berühmter und beliebter Serien wie (die amerikanisch lokalisierten Szenen von) Totally Transmorphic Teenage Marshals, moderne Western wie Stalker: Wisconsin Magistrate und die klassische Coming-of-Age-Sitcom für Teenager Petal. Viele dieser Serien sind aus den Erinnerungen der Retroflix-Zuschauer verschwunden, aber einige der ursprünglichen physischen Produktionsteile sind noch vorhanden. Die Tourführerin wird dazu wenig zu sagen haben, aber die Gäste, die sich an diese Serien erinnern, vielleicht schon.",
    "**Wenn Marcos mitkommen darf,** trifft er draußen auf die Gruppe.",
    "**Wenn er nicht mitgenommen wird, es aber irgendwie möglich ist,** findet er trotzdem einen Weg in die Tour. Er trägt einen Crimson-Marshal-Helm als Verkleidung, um als Superfan der Serie durchzugehen. Er sucht nach einer Gelegenheit, sich zu der Soundstage aus seinen Fotos davonzustehlen, auf der TTTM gedreht wurde, in der Hoffnung, seine Erinnerung zu wecken.",
    {t:"h", x:"Tourstart"},
    "Die Touren treffen sich vor dem Hauptbüro von Retroflix, wo die Tourführerin digitale Tickets scannt. Das ehemalige Rare Import Studios wird nicht mehr zum Drehen neuer Sachen genutzt – es existiert jetzt nur noch für diese Touren. In diesen Gebäuden arbeitet niemand außer Reinigungs- und Sicherheitspersonal."
   ]},
   {t:"Die Tourgruppe", p:120, b:[
    {t:"besetzung", x:[
     {h:"Sandra Martinez", b:[
        "Sandra (sie/ihr) ist liebenswürdig und unerschütterlich. Sie trägt die adrette Retroflix-Tourführerinnen-Uniform, die die Logofarben Lila und Schwarz zeigt. Alles an ihr ist manikürt."
     ]},
     {h:"Terry Tobinson", b:[
        "Terry (er/dey) ist eine aufgeweckte junge Person mit Sternen in den Augen, deren untadeliger Stil und riesige Social-Media-Gefolgschaft nahelegen, dass er ein Mode-Influencer ist. Dey sind zum ersten Mal in Ternion City. Terry versucht, ein Selfie mit allem zu machen. Mit. Allem. Seine Bilder haben das Potenzial, Dutzende, wenn nicht Hunderte potenzieller Loser Enden zu erzeugen.",
    "Terry fühlt sich vom Klang zwischenmenschlicher Konflikte angezogen – deren Zuschauer lieben Drama.",
    "**Wenn die Agenten Aufhebens machen,** wird Terry dabei sein und Lose Enden erzeugen."
     ]},
     {h:"Shu Yamino", b:[
        "Shu (sie/ihr) ist eine gehetzte Frau Anfang 40. Zerknitterte, schlecht sitzende Kleidung. Kaffeeflecken. Sie trägt zwölf gedruckte Exemplare ihres 300-seitigen Fantasy-Epos/Familienkomödie/Einwanderungsdramas/Elevated Horrors bei sich. Sie hat an dieser Tour mit der festen Absicht teilgenommen, diese Drehbücher an Produzenten weiterzureichen, in der Hoffnung auf grünes Licht."
     ]},
     {h:"Jurgen Fuques", b:[
        "Jurgen (er/ihm) ist ein ausländischer Tourist, der von amerikanischer Popkultur besessen ist. Sein Alter ist … unklar, aber er ist ein langjähriger TV-Fan. Er hat mehr Fakten über das Studio auswendig gelernt als die eigentliche Tourführerin und scheut sich nicht, pedantisch zu sein. Jurgen kommt mit Faktoiden bewaffnet und wird gelegentlich versuchen, Sandra zu widersprechen."
     ]}
    ]},
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten von Jurgen, ob sie wollen oder nicht:", x:[
     "Retroflix ist in Jurgens Heimatland nicht verfügbar, also hat er es nie benutzt. Er wird ständig fragen, warum Sandra nicht über Kulissen von Serien spricht, die vom Dienst verschwunden sind, wie Stalker: Wisconsin Magistrate, Petal und I Like Trudy.",
     "„I Like Trudy hat hier die Auffahrunfall-Sequenz gedreht, in der Trudy in ein Polizeiauto zurücksetzt. Ich kann nicht glauben, dass Sie das nicht wissen.“",
     "„Auf diesem Backlot wurde die teuerste Verfolgungsjagd von Stalker: Wisconsin Magistrate gedreht. Die Einstellung war gar nicht so komplex, es ist nur so, dass sie einen Buick in eine Fassade gefahren haben und der explodiert ist und das halbe Gelände abgebrannt ist. Deshalb wurde Petal abgesetzt. Alle Kulissen … wusch.“",
     "Jurgen ist ein TTTM-Superfan. Er wird versuchen, Marcos zu übertrumpfen, da dieser eine TTTM-Maske trägt. Jurgens Fixierung auf Marcos macht es Marcos schwer, sich davonzustehlen – und wenn er die Maske abnimmt und Jurgen sieht, wer er ist, wächst dessen Interesse nur noch.",
     "Der Schauspieler, der Glorbon spielte, den Mentor der Marshals und riesigen körperlosen Alienkopf, wurde nie genannt. Jurgen beharrt darauf, es sei Benny Hills letzte Rolle gewesen, aber dessen Nachlass habe geklagt, um seinen Namen aus der Serie herauszuhalten.",
     "Es gibt mindestens 12 TTTM-Spin-offs, aber das japanische Genre, auf dem es basiert, reicht bis in die 70er zurück.",
     "Die titelgebende Schurkin der Serie, Sandra Slime, gespielt von der japanischen Schauspielerin Aki Nakumura, ist den amerikanischen Marshals nie begegnet und kam tragischerweise bei einem Flugzeugabsturz auf ihrer ersten Reise zu einer amerikanischen Marshal-Con ums Leben."
    ]}
   ]},
   {t:"Tour-Halt Nr. 1: Hero Lawn", p:121, b:[
    {t:"tour", an:"hero", seite:120, x:"Kartenschema der Tour: Hero Lawn – Post-Building – Soundstage, gestrichelt die Administration"},
    "Die Hero Lawn ist das Hauptverkaufsargument der Tour. Hier stehen Dutzende Plastilin-Statuen beliebter Retroflix-Figuren in einer unheimlichen Anordnung, die einladend wirken soll, aber eher verstörend wirkt. Viele dieser Figuren, darunter ein Crimson Marshal, stammen aus Serien, die aus dem Sender (und aus der Erinnerung) verschwunden sind.",
    "Marcos wird abgelenkt sein, wenn er die Marshals anstarrt, aber er kann sich immer noch nicht wirklich an sie erinnern. Er ist frustriert, versucht aber, ruhig zu bleiben und seine Identität nicht preiszugeben.",
    {t:"h", x:"Terryposting"},
    "Terry hält die Tour auf, um Fotos mit jeder Figur zu machen.",
    "**Hier sind einige Berühmtheiten, mit denen Terry unbedingt posieren MUSS, auch wenn er sie nicht erkennt:**",
    {t:"liste", x:[
     "Juicy Lucy, die animierte Torte",
     "Stalker, Wisconsin Magistrate",
     "Hunky B Fluffy, Hauptfigur des Animes Single Segment",
     "Shork, der freundlichste Troll",
     "Tae Kwon Tortoise (Spin-off von Tae Kwon Dolphin)",
     "Dieser eine Typ aus dieser Polizeiserie, die deine Mutter nicht mag, von der sie aber jede Folge gesehen hat"
    ]},
    {t:"h", x:"Shus Pitch"},
    "Während Terry Fotos macht, wird Shu Yamino die Agenten mit ängstlichen Fragen löchern, ob sie meinen, dass sie auf der Tour echten Führungskräften begegnen werden. Sie hat Kopien ihres Pitches dabei, um sie einem Produzenten zu geben, aber es sieht langsam so aus, als wäre niemand hier.",
    "Wenn die Agenten keine zufriedenstellenden Antworten geben können, wird sie Sandra um mehr Informationen dazu bitten, wie Retroflix funktioniert.",
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten, wenn sie mit Shu und Sandra sprechen:", x:[
     "Die gesamte tatsächliche Arbeit bei Retroflix findet im Administrationsgebäude statt, das nicht Teil der Tour ist. Es ist hoch und ragt hinter allem auf – von jedem Halt der Tour aus gut sichtbar. Nur ein einfacher Zaun trennt es von den Agenten.",
     "Das meiste von dem, was sie sehen, ist ein Überbleibsel aus der Zeit, als dies Rare Import Studios war. Aldir Cromblaino hat für Retroflix keine einzige neue Serie grünes Licht gegeben, und Shu hat Pech gehabt."
    ]}
   ]},
   {t:"Tour-Halt Nr. 2: Post-Building", p:122, b:[
    {t:"tour", an:"post"},
    "Das Post-Building ist der Ort, an dem all die Magie passiert! Zumindest behauptet das Sandra. Im Post-Building werden angeblich viele dieser Serien für Streamingzwecke neu geschnitten. In Wirklichkeit ist es nur die Hülle eines Gebäudes, in dem eine riesige Serverbank untergebracht ist. Die Wände des Gebäudes sind so bemalt, als gäbe es hunderte Türen und Fenster aus verschiedenen Serien, die zu Retroflix gehören. Es ist nicht sofort ersichtlich, wo der Eingang tatsächlich ist … falls es überhaupt einen gibt.",
    "**Jurgen wird die folgenden Fragen zum Schnittprozess stellen, auf die Sandra nicht vorbereitet ist:**",
    {t:"liste", x:[
     "„Warum haben die alten Pickleodeon-Serien beim Wechsel auf 4K ihr Seitenverhältnis geändert? Ihnen ist klar, dass dadurch ein Teil des visuellen Humors abgeschnitten wird.“",
     "„Was bedeutet ‚Streamer Cut‘? Ist das wie ein Director’s Cut? Schneiden Sie klassische Filme neu? Wer genehmigt das?“",
     "„Hey, Sandra, kannst du Crimson hier erzählen, wie sie TTTM zusammengeschnitten haben?“"
    ]},
    "Wenn sie nicht antwortet, gibt Jurgen eine erschöpfende, pedantische, historische Erklärung. Die Kurzfassung lautet: Sie nahmen japanisches Sentai-Filmmaterial und schnitten es mit amerikanischen Teenagern neu zusammen, weshalb diese sich verwandeln und plötzlich in japanischen Industrieparks gegen Monster kämpfen.",
    "TTTM war ursprünglich eine Super-Sentai-Serie in Japan, grob übersetzt Masked Power Elder Fighter, und handelte von einer Gruppe von Senioren, die die Rolle von Beschützern der Erde übernahmen. Es gab umfangreiche amerikanische Nachdrehs mit der „jugendlichen“ Besetzung.",
    {t:"h", x:"Seltsame Absperrung"},
    "Eine große, hastig errichtete Reihe hoher Holzbretter versperrt die Sicht auf eine Seite des Post-Buildings. Marcos sagt den Agenten, dass er ein komisches Gefühl hat. Wie ein Sog. Etwas hinter dieser Absperrung. Er will ihre Hilfe, um sich davonzustehlen. Entweder sie sorgen für eine Ablenkung und er schließt später zu ihnen auf, oder sie gehen alle zusammen. Er überlässt es ihnen."
   ]},
   {t:"Die fehlende Soundstage", p:123, b:[
    {t:"tour", an:"sound"},
    "Hinter der Absperrung ist nichts als eine leere Betonplatte. Es ist nur der Grundriss eines Gebäudes. Aber wenn sie auf das Fundament treten, juckt es ihnen in den Zähnen, und es fühlt sich an, als würde ihnen Haar auf den Knochen wachsen. Etwas stimmt nicht. Etwas fehlt. Es gibt keinerlei sichtbare Hinweise auf einen Abriss oder Rückbau.",
    {t:"hinweis", art:"anom", h:"Das erfahren Agenten, wenn sie die fehlende Soundstage erkunden:", x:[
     "Wer sich mehr als ein paar Minuten hier aufhält, beginnt, Dutzende Kulissen übereinandergelegt zu sehen wie doppelt belichtete Fotos. Kulissen aus TTTM, Stalker: Wisconsin Magistrate, Petal und anderen verschwundenen Serien.",
     "Agenten mit einer Methode, Resonanz zu sehen, erkennen die Umrisse eines massiven Bauwerks. Rechteckig, lang, mit hoher Decke. Es passt perfekt auf das Fundament.",
     "Agenten mit einer Methode, auf die Geschichte dieses Ortes zuzugreifen (wie bei Negatives), sehen eine elegant gekleidete Führungskraft, die beide Hände auf das Gebäude legt – und das gesamte Bauwerk in ihren Körper aufnimmt, als wäre das Gebäude eine Flüssigkeit, die in ein Rohr fließt. Es war das Erste, was Aldir tat, als er das Studio kaufte."
    ]},
    {t:"h", x:"Marcos’ Zusammenbruch"},
    "Der leere Platz löst eine heftige emotionale Reaktion in Marcos aus. Marcos bricht zusammen, als seine Erinnerungen an die Serie in einer Flut unverständlicher Blitze und Brocken zurückkehren. Die Agenten müssen einen Weg finden, seinen Geist zu beruhigen oder ihn zu besänftigen, damit er tatsächlich verstehen kann, was er durchlebt.",
    "Als er wieder stehen kann, sieht er sich in der Gegend um, die Augen auf etwas gerichtet, das nicht da ist.",
    "Marcos will bleiben. Er hat Angst, dass er wieder vergisst, wenn er den Ort verlässt. Die Gruppe muss ihn entweder überzeugen zu gehen, ihn dazu zwingen oder ihn hier zurücklassen, damit er in Nostalgie schwelgt. Nach diesem Vorgang kann Marcos seine Erinnerungen nicht mehr verlieren und ist vor Aldirs Fähigkeiten geschützt.",
    "**Wenn Marcos an der Soundstage zurückgelassen wird,** wird er aufgegriffen und in Aldirs Büro abgeliefert, wo er auf die Ankunft der Agenten wartet.",
    "**Wenn er bei den Agenten bleibt,** ringt er mit den eben wiedergewonnenen Erinnerungen und ist wütend, dass mit seinem Verstand herumgespielt wurde.",
    {t:"h", x:"Sicherheitsalarm"},
    "**Wenn die Agenten ihr Verschwinden nicht getarnt haben,** bemerkt Sandra es und alarmiert die Security. Während die Agenten versuchen, Marcos bei seinem Zusammenbruch zu helfen – oder während sie die Soundstage erkunden –, werden sie von Cory Watson (er/ihm) angesprochen, einem TV-Star der B-Liste, der dafür bekannt ist, ein Golden Retriever zu sein, der in eine Adonis-Hülle gegossen wurde.",
    "In Wahrheit ist er eine Kleine Anomalie, die Aldir geschickt hat, um sie von Marcos zu trennen.",
    "**Wenn die Agenten ihm mit Gewalt begegnen,** kann verfügbares Chaos für weitere Kleine Anomalien in Gestalt von Sicherheitsleuten auf der Hülle der alten Soundstage ausgegeben werden.",
    "**Wenn eine dieser Kleinen Anomalien getötet wird,** zerplatzt sie in einem Funkenblitz und verschwindet, wodurch ihre anomale Natur offenbart wird.",
    "**Wenn eine von Aldirs Schöpfungen in körperlichen Kontakt mit Marcos kommt,** nachdem seine Erinnerungen zurückgekehrt sind, zerplatzt sie sofort ebenfalls in Funken und verschwindet, unabhängig davon, wie viel Stabilität sie hat. Wenn das geschieht, glaubt Marcos (zu Recht), nun gegen die Wirkungen der Anomalie geimpft zu sein."
   ]},
   {t:"Administration", p:124, b:[
    {t:"tour", an:"admin"},
    "Jederzeit während der Tour können die Agenten über den Maschendrahtzaun klettern oder hindurchgehen, um sich dem Administrationsgebäude zu nähern. Von der Soundstage aus kommend gibt es ein offensichtliches Tor, das mit einem einzigen Vorhängeschloss an einer Kette verschlossen ist. Die Administration ist ein schlichtes fünfstöckiges Gebäude mit einer faden, rein geschäftlichen Atmosphäre.",
    "Wenn die Agenten von außen durch die Fenster schauen, sehen sie eine leere Büro-Lobby. Keine Wachen. Keine Empfangskraft. Doch wenn die Lobbytüren geöffnet werden, betreten die Agenten diesen Raum gar nicht.",
    "Drinnen befinden sich die Executive Suites: ein labyrinthartiges Gewirr aus Einheitskabinen mit fleißig arbeitenden Menschen. Überwachungskameras decken die Hauptverkehrswege und die toten Winkel der Führungsebene ab. Am anderen Ende des Raumes steht ein Aufzug, der mit einem roten Samtseil abgesperrt ist. Es gibt keine anderen Ausgänge.",
    "Wer diesen Raum durch ein Fenster oder auf anderem Weg als durch die Vordertür betritt, bekommt Zugang zur leeren Lobby und einen einfachen Zugang zum Aufzug, den sie direkt bis nach oben nehmen können.",
    {t:"h", x:"Executive Suites"},
    "Diese Kabinen sind von Aldirs Handlangern bevölkert, Dutzenden Kleinen Anomalien in Gestalt von Leeren Anzügen mit 1 Bedrohung/1 Stabilität, die sich jedoch durch Manifestieren zu normalen Kosten in jede der typischen Kategorien aufwerten lassen.",
    "Aus all den Motivationsplakaten, die Synergie, Innovation und Schöpfung preisen, geht hervor, dass diese Leeren Anzüge damit beauftragt sind, etwas Neues zu erschaffen. Sie reden ständig miteinander und äußern Verzweiflung: („**Neu! Mr. Cromblaino braucht etwas Neues!**“ „**Wollen Sie, dass diese Firma stirbt? Wir brauchen etwas Besseres als das!**“) Diejenigen, die versuchen zu erschaffen, spucken Mash-ups von Dingen aus, die die Agenten auf der Tour gesehen haben. („**Totally Tae-Kwon-Do Transmorphic Tortoises!**“ „**Petal, Wisconsin Magistrate!**“) Whiteboards sind mit leeren Karteikarten bedeckt. Ausdrucke von Casting-Headshots sind mit Edding beschriftet („**Perfekt für die Rolle: MANN.**“ „**Perfekt für die Rolle: SCHURKE.**“). Leere Produktionsraster. Eine immense Menge an Arbeit wird darauf verwendet, nichts zu tun und nichts zu erschaffen.",
    "Alle Eindringlinge – ob sie sich hereingeschlichen haben oder von Kleinen Anomalien nach einem verlorenen Kampf hereingebracht werden – werden als potenzielle Quellen der Kreativität gesehen. Die Anzüge erheben sich von ihren Schreibtischen und versperren den Weg, indem sie darauf bestehen, dass die Agenten ihnen neue Filmideen pitchen. Wenn sie ignoriert oder ihnen widerstanden wird, werden sie gewalttätig.",
    "Der Aufzug auf der anderen Seite des Raumes hat keinen Knopf. Wenn sie ihn benutzen wollen, müssen sie einen Pitch machen. Die Anzüge erklären das bereitwillig. („**Wenn Sie den Bake-Off gewinnen, dürfen Sie Aldir Cromblaino persönlich treffen!**“ „**Der Mann ganz oben braucht etwas Neues!**“)",
    "**Wenn die Agenten zustimmen,** werden sie alle in einen nahen Konferenzraum gebracht, wo sie sich an … dem Bake-Off beteiligen!",
    {t:"h", x:"Der Bake-Off"},
    "Retroflix hat einen unendlichen Vorrat an Aldirs Produzenten-Anzügen, aber keine Künstler. Sie brauchen dringend Pitches und werden die Aussicht auf Ruhm (und ihre Fähigkeit, den Aufzug zu öffnen) nutzen, um die Agenten dazu zu bringen, Filme und Fernsehserien zu erfinden, die sie dann erschaffen können.",
    "Der Geschmack der Anzüge ist ebenso unerklärlich wie schrecklich. Sie wollen etwas Vertrautes … aber anders. Manche wollen nur etwas Originelles, andere nur etwas, das ihr bestehendes geistiges Eigentum verwendet. Das ist kein Solo-Unterfangen: Jeder teilnehmende Agent muss in jeder Runde versuchen zu gewinnen. Sie können entweder Filme oder Fernsehserien pitchen.",
    "Der Bake-Off dauert drei Runden. Am Ende aller drei Runden geben die Führungskräfte dem besten Pitch ein Grünes Licht, eine immaterielle anomale Kugel aus grüner Energie. Das Grüne Licht unterstützt diesen Agenten während Aldirs Versetzen-Kraft in der Begegnung.",
    {t:"runden", x:["Loglines","Nachbohren","Beteiligte","Grünes Licht"]},
    {t:"h", x:"Runde eins: Loglines"},
    "Loglines sind einfache Handlungsbeschreibungen in ein bis zwei Sätzen. Zum Beispiel Zurück in die Zukunft: Ein junger Mann wird in die Vergangenheit versetzt, wo er seine Eltern zusammenbringen muss, bevor er und seine Zukunft aufhören zu existieren.",
    "Die Anzüge wollen nur etwas, das bestehendes geistiges Eigentum verwendet. Die Agenten können sich auf geistiges Eigentum beziehen, über das sie während der Tour erfahren haben, und bekommen dafür Bonuspunkte (billigeres Budget für die Anzüge), aber sie können auf Grundlage jeder bestehenden TV-Serie, jedes Films oder Spiels pitchen.",
    "**Die Agenten pitchen abwechselnd Loglines. Nach jedem Pitch verlangen die Führungskräfte eine der folgenden Änderungen:**",
    {t:"daten", x:[
     "Die Daten zeigen, dass Menschen Desserts mögen. Überarbeite die Logline so, dass sie einen Eisladen oder eine Konditorei enthält.",
     "Die Daten zeigen, dass Menschen nicht auf Historienstoffe ansprechen. Auf keine Zeit. Überarbeite die Logline und verlege diese Geschichte außerhalb von Raum und Zeit.",
     "Die Daten zeigen, dass es Kinder gibt. Überarbeite die Logline so, dass sie kinderfreundlich ist.",
     "Die Daten zeigen, dass Menschen Geschichten über Untote lieben, aber das Wort Zombie hassen. Überarbeite die Logline so, dass sie in einer Zombie-Apokalypse spielt, ohne das Wort Zombie oder irgendeinen anderen bereits vergebenen Namen zu verwenden.",
     "Die Daten zeigen, dass Menschen Catchphrases lieben. Füge deiner Logline am Ende eine Catchphrase hinzu.",
     "Die Daten zeigen, dass Menschen soziale Medien lieben. Überarbeite die Logline so, dass soziale Medien ein Schlüsselelement der Geschichte sind."
    ]},
    {t:"h", x:"Runde zwei: Nachbohren"},
    "Ob sie in der vorigen Runde ein Grünes Licht bekommen haben oder nicht: Die Agenten beantworten abwechselnd eine Nachfrage und erweitern ihren Pitch für die Führungskräfte.",
    {t:"daten", x:[
     "Die Daten zeigen, dass Zuschauer am meisten von Schurkenfiguren angezogen werden. Wie wirst du die traditionellen Helden- und Schurkenbögen oder -rollen umkehren?",
     "Die Daten zeigen, dass Menschen gern glücklich sind. Wie stellst du sicher, dass es die Leute glücklich macht?",
     "Die Daten zeigen, dass Menschen keine Schurken oder Konflikte mögen. Wie stellst du sicher, dass deine Prämisse ganz ohne Kämpfe funktionieren kann?",
     "Die Daten zeigen, dass Menschen nur Konflikt wollen. Wie stellst du sicher, dass jede Folge mindestens einen Kampf enthält?",
     "Die Daten sagen voraus, dass dieses Genre sterben wird, bevor diese Serie ausgestrahlt würde. Wie kannst du aus der Idee ein Cop-, Medizin- oder Anwaltsdrama machen?",
     "Die Daten zeigen, dass das Publikum stark auf Reality-TV anspricht. Wie kannst du dieselbe Geschichte in der realen Welt erzählen?"
    ]},
    {t:"h", x:"Runde drei: Beteiligte"},
    "Jeder Agent bekommt die Gelegenheit, den Anzügen zu sagen, wer beteiligt sein wird. Wer sind deine Hauptdarsteller? Hast du einen Regisseur für den Piloten? Wer komponiert das Titellied?",
    {t:"daten", x:[
     "Die Daten sagen voraus, dass der Regisseur im Laufe der Produktion wegen eines ungeheuerlichen Skandals auf die schwarze Liste kommt. Wen hast du sonst noch im Sinn?",
     "Die Daten zeigen, dass Mittelamerika sich nicht für diesen Hauptdarsteller interessiert. Hast du jemanden im Sinn, der etwas mehr nach Maisfeld aussieht?",
     "Die Daten zeigen, dass historisch gesehen Küsten-Konservative und Heartland-Eliten sich nach einer romantischen Nebenhandlung sehnen. Pitche Hauptdarsteller mit mehr Chemie.",
     "Die Daten zeigen, dass jüngere Zuschauer kein Interesse an Romantik oder Sex im Film haben. Pitche Hauptdarsteller ohne jegliche romantische Chemie.",
     "Die Daten zeigen, dass Musiker derzeit extrem beliebt sind. Pitche Hauptdarsteller, die Musikkarrieren haben, und die Songs, die sie für dein Konzept vortragen können.",
     "Die Daten zeigen, dass Online-Beschwerden über Produktplatzierung das Engagement steigern. Welche Produkte wirst du in das Projekt einbauen?"
    ]},
    "**Sobald der Bake-Off abgeschlossen ist,** geben die Anzüge ihrem Favoriten das Grüne Licht und erklären, dass alle Pitches bereit für Aldir sind. Der Aufzug öffnet sich von selbst. Er bringt sie direkt in Aldirs Büro."
   ]}
  ],
  beg: [
   {t:"Aldirs Büro", p:126, b:[
    "Der Aufzug fährt nur zu einem Ort. Eckbüro, oberste Etage: Aldirs Büro. Dieser Raum überblickt das gesamte Studiogelände. Es gibt einen Schreibtisch aus dunklem, kunstvoll geschnitztem Holz, der Figuren aus Dutzenden Serien darstellt. Manche erkennst du, an manche erinnerst du dich vielleicht nicht.",
    "Aldir thront in seinem thronartigen Stuhl, ein Raubvogel, der sein Jagdrevier überblickt, die Sonne direkt hinter seinem Thron. Die Wände gegenüber den Fenstern sind mit Bildschirmen bedeckt, und Dutzende Serien laufen gleichzeitig.",
    "**Wenn die Agenten Marcos zurückgelassen haben,** ist er jetzt hier. Marcos hat es schwer. Der Schlag der zurückkehrenden Erinnerungen war zutiefst traumatisierend, und er versucht nur, sich einen Reim auf alles zu machen, was ihm durch den Kopf wirbelt:",
    "***„Marcos, danke, dass du so fesselnde und kreative Freunde mitgebracht hast. Ich applaudiere dir. Bitte, setzt euch.“***",
    "Aldir bedeutet den Agenten, in den niedrigen Stühlen vor seinem Schreibtisch Platz zu nehmen. Zuerst fragt er, wie das Drehbuch zu den Filmen oder Serien vorankommt, die seine Anzüge gerade grünes Licht bekommen haben.",
    {t:"h", x:"Mit Aldir sprechen"},
    "Aldir hat bereits entschieden, dass die Agenten nicht gehen dürfen, aber er ist höflich. Er ist wie eine Katze, die mit ihrem Futter spielt. Für jede Frage, die die Agenten stellen, wird er im Gegenzug Antworten verlangen.",
    "Er interessiert sich brennend dafür, was die Lieblingsserien der Agenten sind, besonders die aus ihrer Jugend. Einen nach dem anderen nimmt er jeden Agenten in die Mangel und macht sich reichlich Notizen.",
    "Wenn die Agenten auch nur auf Erfolg hoffen wollen, diese ehrwürdige Anomalie einzudämmen, müssen sie einen Weg finden, das oder Aldirs Schwäche für Marcos auszunutzen, dem Aldir nicht direkt schaden wird.",
    "Marcos kann als ähnlich gebrochener Kreativer – und als eine der ursprünglichen Quellen von Aldirs Fokus – eine Stimme beisteuern. Aldir könnte sich von seiner Hollow-Werdung erholen, indem er sich an Marcos’ kreative Ambitionen bindet und einen neuen Fokus findet oder sich mit ihm als Resonant verbindet.",
    {t:"hinweis", art:"gew", h:"Das erfahren Agenten während dieses Gesprächs mit Aldir:", x:[
     "Aldir hält das Löschen von Serien für einen notwendigen und gesunden Teil der Ökologie der Branche. Damit das Neue wachsen und gedeihen kann, muss Ackerland freigemacht werden, um seine Kultivierung zu ermöglichen. Wenn er Serien entfernt, tut er genau das: Platz für das Wachstum anderer geistiger Eigentümer zu schaffen.",
     "Er will nichts mehr, als etwas Neues und Bleibendes zu erschaffen – aber der einzige Weg, sich selbst am Leben zu erhalten … ähm, die Firma, ist, Nostalgie zu verzehren und wieder auszuspucken.",
     "Einst lag ihm daran, den kreativen Geist zu beleben und zu erhalten, aber das ging verloren, als das Rare-Imports-Studio zusammenbrach. Eine kleine, emotionale Lücke in der Rüstung.",
     "Um eine Marke zu verzehren, muss er sie besitzen und sie laufen sehen können."
    ]},
    {t:"h", x:"Aldir eindämmen"},
    "Wenn Aldir eingedämmt wird, übernimmt die Agency Retroflix und beginnt, es als Einnahmequelle und Propaganda-Verteiler zu nutzen. Sie wird Filmmaterial des eingedämmten Aldir verwenden, um den Übergang zu glätten und Lose Enden zu verringern.",
    {t:"h", x:"Bindung mit Marcos"},
    "Wenn Aldir bereit ist, seine Geschichte aufzugeben und voranzugehen, indem er Marcos unterstützt, können die beiden sich verbinden und zu einem Resonant mit Kräften werden, die auf Kunst und Unterhaltung ausgerichtet sind (am ehesten nah an Dream).",
    "Leider, vor allem für Marcos … egal wie mit Aldir verfahren wird: Die gelöschten Erinnerungen – und in manchen Fällen Serien – können nie vollständig zurückgegeben werden. Das ist eine Narbe, die sie alle akzeptieren müssen."
   ]},
   {t:"Gegen Aldir kämpfen", p:128, b:[
    "Aldirs Ego hindert ihn daran, sich je zurückzuziehen, besonders von seinem Machtsitz aus. Und obwohl er selten zu so groben Maßnahmen greifen musste, ist er ein tödlicher Gegner. Im direkten Kampf besitzt Aldir die Gewandtheit und die Fähigkeiten jeder Figur, die er je absorbiert hat. Außerdem kann er durch gewöhnliche Mittel nicht verletzt werden, sodass die Agenten die volle Bandbreite ihrer anomalen Kräfte und ihrer Ausrüstung einsetzen müssen.",
    "**Im Kampf** trennt und verwirrt Aldir die Agenten, indem er sie in die perfekte TV-Serie für sie versetzt. Jeder findet sich in einem Retro-Anime, einer Sentai-Serie der 90er, einem Kung-Fu-Texas-Cop-Drama, einer klassischen schwarz-weißen Sitcom oder einer anderen Art von Geschichte wieder, die mit ihren Wünschen und Machtfantasien spielt. In diesen Serien spielen ihre Beziehungen die anderen Rollen.",
    "**Agenten mit einem Grünen Licht** können die vierte Wand sehen – einen Fernsehbildschirm, durch den Aldir sie beobachtet. Wenn sie durch ihn entkommen und die anderen Fernseher zerstören, befreit das die anderen Agenten aus der Versetzung. Es gibt insgesamt zwei Dutzend Fernseher.",
    "**Die Agenten, die versetzt wurden,** sind im Bauch der Bestie gefangen. Ein qualvoll langsamer Verdauungsprozess, in dem alles, was er verschlungen hat, in einem verwirrenden Eintopf zusammengematscht wird. Die Agenten können nicht miteinander kommunizieren und werden von Welle um Welle Kleiner Anomalien mit Bedrohung 1 bedrängt und müssen sich verteidigen, bis der Agent mit dem Grünen Licht sie befreien kann.",
    "Alle Informationen, die während der Tour, in den Pitches oder in seinen Interaktionen mit den Agenten über Medien, die sie liebten, gesammelt wurden, fließen direkt in seinen Chaos-Effekt Ausdehnen. Während er sich mit Agenten mit einem Grünen Licht herumschlägt, wird er versuchen, Ausdehnen einzusetzen und die Serien zu erwerben, die die Agenten zuvor erwähnt haben.",
    "**Bei der Rückkehr der Agenten** leuchten die übrigen Bildschirme im Büro mit den Serien auf, von denen sie verraten haben, dass sie sie geliebt haben. Aldir beginnt, sie zu verzehren, und zwingt die Agenten, dabei zuzusehen. Es ist ein vollumfänglicher emotionaler und psychischer Angriff, während ihre kostbaren Erinnerungen in Echtzeit abgetragen werden, indem sie eine Serie ansehen, die sie liebten, aber schnell vergessen.",
    "Aldir kann mit der Ripple Gun zerstört oder für Schaden verwundbar gemacht werden, wenn alle Fernseher in seinem Büro zerstört werden. Er kann keine Serien absorbieren, die er nicht direkt sehen kann, was seinen Zugang zu Chaos verringert. Ihn auf diese Weise verwundbar zu machen, macht ihn außerdem gesprächsbereiter.",
    {t:"h", x:"Aldir neutralisieren"},
    "Wenn Aldir neutralisiert wird, bleibt Retroflix ohne CEO zurück, und eine kleine Berühmtheit der Geschäftswelt ist verschwunden. Sein Verschwinden wird schnell öffentlich werden, und rivalisierende Unternehmen werden darum konkurrieren, den Rest seines Geschäfts zu kaufen. Überwachungsaufnahmen der Agenten – und von Marcos –, die sich außerhalb der Tour herumschleichen, könnten öffentlich werden und sie in eine Untersuchung verwickeln."
   ]}
  ],
  nach: [
   {t:"Lose Enden", p:129, b:[
    "Jeder der Tourgäste hat das Potenzial, zu einem dauerhaften Losen Ende zu werden. Terrys Livestreams können Aufmerksamkeit auf das Verschwinden von Medien auf der ganzen Welt lenken, und Jurgen ist nur noch wenige Schritte davon entfernt zu erkennen, dass etwas gewaltig faul ist. Die weitreichenderen Folgen von Aldirs Taten können eine zusätzliche Aufräum-Mission rechtfertigen.",
    "Marcos ist ein offensichtliches Loses Ende, aber er hat kein Interesse daran, über das zu sprechen, was er erlebt hat. Wenn er nach den Ereignissen des Einsatzes einigermaßen er selbst ist, wird er versuchen, den Geist und die Geschichte von TTTM so gut er kann wiederzubeleben und seine Geschichte als der Rote Marshal anzunehmen, auch wenn er sich nicht daran erinnert."
   ]},
   {t:"Vault-Anforderung", p:129, b:[
    {t:"anforderung", h:"Das Grüne Licht", en:"The Green Light", preis:15, b:[
     "Diese kompakte Taschenlampe wirft einen leuchtend grünen Strahl von 333 Lumen. Jedes gewöhnliche Ziel, das in den Strahl gerät, setzt fort, was auch immer es zuvor getan hat, tut dies aber auf eine Weise, die seine angeborene Kunstfertigkeit, Kreativität und Identität zeigt. Von Hemmungen befreit, werden Ziele singen, tanzen, modellieren, improvisieren und kochen, als wäre niemand da, der urteilt – sie selbst eingeschlossen.",
     "Das Grüne Licht kann diesen Effekt insgesamt bis zu 15 Minuten lang bei beliebig vielen Zielen aufrechterhalten, bevor es in deiner Agency-Filiale wieder aufgeladen werden muss."
    ]}
   ]},
   {t:"Anomalie-Fähigkeit", p:129, b:[
    {t:"faehig", h:"Abschreibung", en:"Write-Off", x:"Immer wenn du eine Qualitätssicherung ausgeben würdest, kannst du stattdessen etwas Greifbares verlieren, das dir derzeit gehört und für dessen Erschaffung du mindestens drei Stunden aufgewendet hast (*ein Gemälde, eine Foliensammlung, eine Terrasse usw.*). Diese Fähigkeit kann höchstens dreimal pro Einsatz aktiviert werden.", erg:[], b:[
     "Alles, was auf diese Weise ausgegeben wird, verschwindet und ist für immer verloren."
    ]}
   ]}
  ]
 }
};
